use serde_json::Value;

pub fn solve(input: serde_json::Value) -> serde_json::Value {
    let year = input["input"][0].as_i64().unwrap();
    let month = input["input"][1].as_i64().unwrap();
    let days_in_month = match month {
        1 => 31,
        2 => 28,
        3 => 31,
        4 => 30,
        5 => 31,
        6 => 30,
        7 => 31,
        8 => 31,
        9 => 30,
        10 => 31,
        11 => 30,
        12 => 31,
        _ => 0,
    };
    serde_json::Value::Number(days_in_month as f64)
}
